"""Writes shell_ext/exts.h from convert_win.formats.EXT_TYPE keys (lower-case, with dot).

Run from the repo root: .venv-win/Scripts/python.exe tools/gen_ext_header.py
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from convert_win.formats import EXT_TYPE  # noqa: E402

OUT = ROOT / "shell_ext" / "exts.h"


def build() -> str:
    exts = sorted({f".{e.lower()}" for e in EXT_TYPE})
    lines = [
        "// Generated by tools/gen_ext_header.py from convert_win.formats.EXT_TYPE. Do not edit.",
        "#pragma once",
        "static const wchar_t* const kExts[] = {",
    ]
    lines += [f'    L"{e}",' for e in exts]
    lines += [
        "};",
        f"static const size_t kExtCount = {len(exts)};",
        "",
    ]
    return "\n".join(lines)


if __name__ == "__main__":
    text = build()
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {OUT} ({text.count(chr(10))} lines)")
